function escapeHtml(value="") { return String(value).replace(/[&<>'"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c])); }
function initials(name) { return name.split(/\s+/).map(x=>x[0]).slice(0,2).join("").toUpperCase(); }
function showToast(message){const t=document.querySelector("#toast");t.textContent=message;t.classList.add("show");clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove("show"),2200);}
function sectionHeader(title,desc,actionLabel,actionType){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${actionLabel?`<button class="button primary" data-add="${actionType}"><span>＋</span>${actionLabel}</button>`:""}</div>`;}
const collectionNames={committee:"committees",hearing:"hearings",amendment:"amendments","bill-version":"billVersions",vote:"votes",jurisdiction:"jurisdictions",session:"sessions",chamber:"chambers",contact:"contacts",organization:"organizations",engagement:"engagements",position:"positions",document:"documents","report-template":"reportTemplates","saved-search":"savedSearches","client-profile":"clientProfiles","impact-assessment":"impactAssessments","media-mention":"mediaMentions"};
function collectionFor(type){return type==="bill"?bills:type==="schedule-event"?searchEvents():state[collectionNames[type]||`${type}s`]||[];}
function idByName(type,name){const field=type==="bill"?"id":type==="keyword"?"term":"name";return collectionFor(type).find(x=>x[field]===name)?.id;}
function objectRef(type,id,label,className="object-link"){return id!==undefined?`<button type="button" class="${className}" data-object-type="${type}" data-object-id="${escapeHtml(id)}">${label}</button>`:label;}
function evidenceRef(value){const text=String(value);const bill=bills.find(item=>text.startsWith(item.id));return bill?objectRef("bill",bill.id,`▱ ${escapeHtml(text)}`):`<button type="button">▱ ${escapeHtml(text)}</button>`;}
function avatars(names,type="client"){return `<div class="avatar-stack">${names.slice(0,3).map((n,i)=>{const id=idByName(type,n);return id!==undefined?`<button type="button" class="object-avatar" style="--i:${i}" title="${escapeHtml(n)}" aria-label="${escapeHtml(n)}" data-object-type="${type}" data-object-id="${escapeHtml(id)}">${initials(n)}</button>`:`<span style="--i:${i}" title="${escapeHtml(n)}" aria-label="${escapeHtml(n)}">${initials(n)}</span>`;}).join("")}${names.length>3?`<em title="${escapeHtml(names.slice(3).join(", "))}">+${names.length-3}</em>`:""}</div>`;}
function clientProfileFor(name){return state.clientProfiles.find(profile=>profile.client===name);}
function legislatorOffice(legislator){return state.legislativeOffices.find(office=>office.legislatorId===legislator.id&&office.status==="Current");}
function legislatorMemberships(legislator){return state.committeeMemberships.filter(membership=>membership.legislatorId===legislator.id&&membership.status==="Current");}
function committeeSessionForMembership(membership){return state.committeeSessions.find(session=>session.id===membership.committeeSessionId);}
function committeeForMembership(membership){return getObject("committee",committeeSessionForMembership(membership)?.committeeId);}
function currentCommitteeSession(committee){return state.committeeSessions.find(session=>session.committeeId===committee.id&&session.status==="Active");}
function committeeMembershipsFor(committee){const session=currentCommitteeSession(committee);return state.committeeMemberships.filter(membership=>membership.committeeSessionId===session?.id&&membership.status==="Current");}
function committeeReferralsFor(committee){const session=currentCommitteeSession(committee);return state.billReferrals.filter(referral=>referral.committeeSessionId===session?.id);}
function committeeStaffFor(committee){const session=currentCommitteeSession(committee);return state.committeeStaffAssignments.filter(assignment=>assignment.committeeSessionId===session?.id&&assignment.status==="Current");}
function committeeBills(committee){return committeeReferralsFor(committee).map(referral=>referral.billId);}
function committeeChair(committee){const membership=committeeMembershipsFor(committee).find(item=>item.role.includes("Chair"));return membership?getObject("legislator",membership.legislatorId):null;}
function legislatorLeadership(legislator){return state.leadershipAssignments.filter(assignment=>assignment.legislatorId===legislator.id&&assignment.status==="Current");}
function legislatorElections(legislator){return state.electionHistory.filter(election=>election.legislatorId===legislator.id);}
function legislatorSponsorships(legislator){return state.billSponsorships.filter(sponsorship=>sponsorship.legislatorId===legislator.id&&sponsorship.status==="Current");}
function legislatorStaff(legislator){return state.staffAssignments.filter(assignment=>assignment.legislatorId===legislator.id&&assignment.status==="Current");}
function renderImpactStrip(billId){const assessments=state.impactAssessments.filter(a=>a.bill===billId);if(!assessments.length)return "";return `<div class="impact-strip"><span>✦ CLIENT IMPACT</span><div>${assessments.map(a=>`<button data-object-type="impact-assessment" data-object-id="${a.id}"><b>${initials(a.client)}</b><span>${a.materiality} · ${a.direction}</span><i class="review-dot ${a.reviewStatus.toLowerCase().replaceAll(" ","-")}"></i></button>`).join("")}</div></div>`;}

