  if(type==="theme"){x.issues.forEach(n=>add("issue",idByName("issue",n),n,"Issue"));state.keywords.filter(k=>k.themes.includes(x.name)).forEach(k=>add("keyword",k.id,k.term,`${k.hits} matches`));bills.filter(b=>b.themes.includes(x.name)).forEach(b=>add("bill",b.id,b.id,b.status));state.impactAssessments.filter(a=>a.themes.includes(x.name)).forEach(a=>add("impact-assessment",a.id,a.name,a.materiality));const clients=[...new Set(x.issues.flatMap(i=>state.issues.find(issue=>issue.name===i)?.clients||[]))];clients.forEach(n=>add("client",idByName("client",n),n,"Client"));}
  if(type==="bill"){const tracked=billReview(x).tracked;if(tracked){state.impactAssessments.filter(a=>a.bill===x.id).forEach(a=>add("impact-assessment",a.id,a.name,`${a.materiality} · ${a.reviewStatus}`));x.clients.forEach(n=>add("client",idByName("client",n),n,"Client"));x.issues.forEach(n=>add("issue",idByName("issue",n),n,"Issue"));x.themes.forEach(n=>add("theme",idByName("theme",n),n,"Theme"));state.positions.filter(p=>p.bill===x.id).forEach(p=>add("position",p.id,p.name,p.stance));state.reports.filter(r=>r.bills.includes(x.id)).forEach(r=>add("report",r.id,r.name,"Report"));}add("legislator",idByName("legislator",x.sponsor),x.sponsor,"Sponsor");state.committees.filter(c=>committeeBills(c).includes(x.id)).forEach(c=>add("committee",c.id,c.name,"Committee"));state.hearings.filter(h=>h.bills.includes(x.id)).forEach(h=>add("hearing",h.id,h.name,h.date));state.billVersions.filter(v=>v.bill===x.id).forEach(v=>add("bill-version",v.id,v.name,v.status));state.amendments.filter(a=>a.bill===x.id).forEach(a=>add("amendment",a.id,a.name,a.status));state.votes.filter(v=>v.bill===x.id).forEach(v=>add("vote",v.id,v.name,v.result));state.documents.filter(d=>d.bill===x.id).forEach(d=>add("document",d.id,d.name,d.version));state.mediaMentions.filter(item=>item.bills.includes(x.id)).forEach(item=>add("media-mention",item.id,item.name,item.outlet));}
  if(type==="keyword"){if(x.groupType!=="Standalone")add(x.groupType.toLowerCase(),idByName(x.groupType.toLowerCase(),x.group),x.group,x.groupType);x.themes.forEach(n=>add("theme",idByName("theme",n),n,"Theme"));}
  if(type==="user")state.clients.filter(c=>c.owner===x.name).forEach(c=>add("client",c.id,c.name,"Assigned client"));
  if(type==="legislator"){legislatorSponsorships(x).forEach(sponsorship=>{const bill=getObject("bill",sponsorship.billId);add("bill",sponsorship.billId,sponsorship.billId,`${sponsorship.role} · ${bill?.status}`);});legislatorMemberships(x).forEach(membership=>{const committee=committeeForMembership(membership);add("committee",committee?.id,committee?.name,membership.role);});legislatorStaff(x).forEach(assignment=>add("contact",assignment.contactId,getObject("contact",assignment.contactId)?.name,assignment.role));state.mediaMentions.filter(item=>item.legislators.includes(x.name)).forEach(item=>add("media-mention",item.id,item.name,item.outlet));}
  if(type==="report"){add("client",idByName("client",x.client),x.client,"Client");x.issues.forEach(n=>add("issue",idByName("issue",n),n,"Issue"));state.themes.filter(t=>t.issues.some(i=>x.issues.includes(i))).slice(0,3).forEach(t=>add("theme",t.id,t.name,"Theme"));x.bills.forEach(id=>add("bill",id,id,getObject("bill",id)?.status));state.impactAssessments.filter(a=>a.client===x.client&&x.bills.includes(a.bill)).forEach(a=>add("impact-assessment",a.id,a.name,a.reviewStatus));add("report-template","weekly-client-update","Weekly Client Update","Template");}
  if(type==="client-profile"){add("client",idByName("client",x.client),x.client,"Client");state.impactAssessments.filter(a=>a.profile===x.id).forEach(a=>add("impact-assessment",a.id,a.name,a.reviewStatus));}
  if(type==="impact-assessment"){add("client",idByName("client",x.client),x.client,"Client");add("client-profile",x.profile,getObject("client-profile",x.profile)?.name,"Profile input");add("bill",x.bill,x.bill,"Bill");if(x.billVersion)add("bill-version",x.billVersion,getObject("bill-version",x.billVersion)?.name,"Bill version");x.themes.forEach(n=>add("theme",idByName("theme",n),n,"Theme"));add("user",idByName("user",x.reviewer),x.reviewer,"Reviewer");}
  if(type==="committee"){const jurisdictionId=idByName("jurisdiction",x.jurisdiction),chamber=state.chambers.find(item=>item.jurisdiction===jurisdictionId&&item.name.includes(x.chamber));add("jurisdiction",jurisdictionId,x.jurisdiction,"Jurisdiction");add("chamber",chamber?.id,chamber?.name,"Chamber");committeeMembershipsFor(x).forEach(membership=>{const legislator=getObject("legislator",membership.legislatorId);add("legislator",legislator?.id,legislator?.name,membership.role);});committeeReferralsFor(x).forEach(referral=>add("bill",referral.billId,referral.billId,referral.disposition||referral.status));state.hearings.filter(h=>h.committee===x.id).forEach(h=>add("hearing",h.id,h.name,h.date));committeeStaffFor(x).forEach(assignment=>add("contact",assignment.contactId,getObject("contact",assignment.contactId)?.name,assignment.role));if(x.parentCommitteeId)add("committee",x.parentCommitteeId,getObject("committee",x.parentCommitteeId)?.name,"Parent committee");}
  if(type==="hearing"){add("committee",x.committee,getObject("committee",x.committee)?.name,"Committee");x.bills.forEach(id=>add("bill",id,id,getObject("bill",id)?.title));}
  if(type==="amendment"){add("bill",x.bill,x.bill,getObject("bill",x.bill)?.title);state.documents.filter(d=>d.bill===x.bill).forEach(d=>add("document",d.id,d.name,d.version));}
  if(type==="bill-version"){add("bill",x.bill,x.bill,getObject("bill",x.bill)?.title);state.amendments.filter(a=>a.bill===x.bill).forEach(a=>add("amendment",a.id,a.name,a.status));}
  if(type==="vote"){add("bill",x.bill,x.bill,getObject("bill",x.bill)?.title);if(x.committee)add("committee",x.committee,getObject("committee",x.committee)?.name,"Committee");}
  if(type==="jurisdiction")state.sessions.filter(s=>s.jurisdiction===x.id).forEach(s=>add("session",s.id,s.name,s.status));
  if(type==="session")add("jurisdiction",x.jurisdiction,getObject("jurisdiction",x.jurisdiction)?.name,"Jurisdiction");
  if(type==="chamber"){add("jurisdiction",x.jurisdiction,getObject("jurisdiction",x.jurisdiction)?.name,"Jurisdiction");state.committees.filter(c=>x.name.includes(c.jurisdiction)&&x.name.includes(c.chamber)).forEach(c=>add("committee",c.id,c.name,"Committee"));}
  if(type==="contact"){state.engagements.filter(g=>g.contacts.includes(x.id)).forEach(g=>add("engagement",g.id,g.name,g.date));state.staffAssignments.filter(assignment=>assignment.contactId===x.id&&assignment.status==="Current").forEach(assignment=>add("legislator",assignment.legislatorId,getObject("legislator",assignment.legislatorId)?.name,assignment.role));state.committeeStaffAssignments.filter(assignment=>assignment.contactId===x.id&&assignment.status==="Current").forEach(assignment=>{const session=state.committeeSessions.find(item=>item.id===assignment.committeeSessionId),committee=getObject("committee",session?.committeeId);add("committee",committee?.id,committee?.name,assignment.role);});}
  if(type==="organization"&&x.id==="california-assembly"){add("jurisdiction","ca","California","Jurisdiction");state.committees.filter(c=>c.jurisdiction==="California").forEach(c=>add("committee",c.id,c.name,"Committee"));}
